import{_ as e,o as a,c as s,a4 as l}from"./chunks/framework.DzJZdBQK.js";const u=JSON.parse('{"title":"打造自己的HTTPS安全遂道","description":"","frontmatter":{"date":"2018-11-02T08:27:18","title":"打造自己的HTTPS安全遂道","categories":["misc"],"tags":["http tunnel","natapp"]},"headers":[{"level":2,"title":"https证书","slug":"https证书","link":"#https证书","children":[]},{"level":2,"title":"http tunnel服务器","slug":"http-tunnel服务器","link":"#http-tunnel服务器","children":[]},{"level":2,"title":"http tunnel客户端","slug":"http-tunnel客户端","link":"#http-tunnel客户端","children":[]},{"level":2,"title":"验证","slug":"验证","link":"#验证","children":[]}],"relativePath":"posts/misc/tunnel.md","filePath":"posts/misc/tunnel.md"}'),i={name:"posts/misc/tunnel.md"};function n(h,t,r,p,o,c){return a(),s("div",null,[...t[0]||(t[0]=[l(`<h1 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h1><p>最近刚好在做小程序的开发，需要用到本地调试，刚开始时使用<code>Natapp</code>的免费遂道，勉强能开发（域免），后面买了付费遂道，域名不变开发顺畅起来。但要真机调试时还是不行，微信不认三级域名，需要购买他的二级域名服务。转念一想还不如自己搭建一个呢，成本可控，也只要折腾一次就好，反正也能学东西。于是也就有了本文。</p><h1 id="准备" tabindex="-1">准备 <a class="header-anchor" href="#准备" aria-label="Permalink to &quot;准备&quot;">​</a></h1><ul><li>一台云主机，可在购买<a href="https://promotion.aliyun.com/ntms/act/qwbk.html#share_box?spm=5176.11533457.1089570.36.15da77e3g6I8CL&amp;aliyunapp_auto_login=true&amp;userCode=l7irb6oi" target="_blank" rel="noreferrer">阿里云</a>，开放对应端口。</li><li>一个已经备案的域名（备案过程真是个痛苦的过程，各种资料，各种步骤，还可能审不过），并且做了二级域名泛解析。（本文假设你已经会域名解析配置）</li><li><code>Go http tunnel</code>，可在这里下载(<a href="https://github.com/mmatczuk/go-http-tunnel/releases" target="_blank" rel="noreferrer">https://github.com/mmatczuk/go-http-tunnel/releases</a>)</li><li>Let&#39;s Encrypt工具。</li></ul><h1 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to &quot;配置&quot;">​</a></h1><h2 id="https证书" tabindex="-1">https证书 <a class="header-anchor" href="#https证书" aria-label="Permalink to &quot;https证书&quot;">​</a></h2><p>可参看<a href="http://www.infoq.com/cn/news/2018/03/lets-encrypt-wildcard-https" target="_blank" rel="noreferrer">这里</a>或<a href="https://www.jianshu.com/p/c5c9d071e395" target="_blank" rel="noreferrer">这里</a> 此处唯一要注意的就是有个域名解析的交互过程，这个在上述资料中也有说明。</p><p>记录下证书的生成位置如上文是<code>/etc/letsencrypt/archive/newyingyong.cn</code>，自动的生成路径可能不现。</p><h2 id="http-tunnel服务器" tabindex="-1">http tunnel服务器 <a class="header-anchor" href="#http-tunnel服务器" aria-label="Permalink to &quot;http tunnel服务器&quot;">​</a></h2><ul><li>服务器需要开放80,443,5223端口。</li><li>根据自己的服务器系统下载对应版本。</li><li>解压就可以了，进入目录。</li><li>执行如下命令，以https证书参考资料证书地址为例。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tunneld -tlsCrt /etc/letsencrypt/archive/goldsyear.com/fullchain.pem -tlsKey /etc/letsencrypt/archive/goldsyear.com/privkey.pem</span></span></code></pre></div><h2 id="http-tunnel客户端" tabindex="-1">http tunnel客户端 <a class="header-anchor" href="#http-tunnel客户端" aria-label="Permalink to &quot;http tunnel客户端&quot;">​</a></h2><ul><li>根据自己的服务器系统下载对应版本</li><li>解压就可以了，进入目录。</li><li>生成客户端证书<code>openssl req -x509 -nodes -newkey rsa:2048 -sha256 -keyout client.key -out client.crt</code>,并将证书放到解压目录</li><li>创建<code>tunnel.yml</code>，默认读当前路径配置。</li><li>参考样例：</li></ul><div class="language-yml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">server_addr</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">SERVER_IP:5223</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tunnels</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    webui</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        proto</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        addr</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">localhost:8080</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        auth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">user:password</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">goldsyear.com</span></span></code></pre></div><p>其中,<code>server_addr</code>为服务器地址，<code>tunnels</code>为开启的遂道列表，<code>webui</code>为实际的遂道名，正常可去掉<code>auth</code>配置，<code>host</code>中的域名与遂道名无直接关系。更多配置信息参看<a href="https://github.com/mmatczuk/go-http-tunnel" target="_blank" rel="noreferrer">官网</a>。</p><ul><li>启动<code>tunnel start-all</code>。</li></ul><h2 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h2><p>在客户端启动最简单http服务，使用客户端配置的域名进行访问，如果正常访问，恭喜你。如果还有问题，请核查服务器或客户端配置。</p><h1 id="推广" tabindex="-1">推广 <a class="header-anchor" href="#推广" aria-label="Permalink to &quot;推广&quot;">​</a></h1><p>如果你觉得以上配置过于复杂。有以下两种方式供你选择，当然你可能有更好的选择。</p><ol><li>可以使用<a href="https://natapp.cn/" target="_blank" rel="noreferrer">Natapp</a>，他提供免费的HTTPS的遂道，但提供的免费域名会一直变化。最好购买遂道和域名服务，付费时可以使用我的推广优惠码<code>ADBE2C5C</code>。</li><li>如果你恰好刚起步，希望用于本地调试，可以加我微信号，也可提供相关服务支持。申请时请备注<code>https tunnel技术支持</code>。<img src="https://l4qiang.me/images/wechat.png" alt="微信"></li></ol>`,21)])])}const k=e(i,[["render",n]]);export{u as __pageData,k as default};
